package earth.terrarium.pastel.data.lang.guidebook.cuisine;

import net.neoforged.neoforge.common.data.LanguageProvider;

public class BloodOrchidProductsEntry {
	public static void addTranslations(LanguageProvider provider) {
		provider.add("book.pastel.guidebook.blood_orchid_products.name", "Blood Orchid Products");
		provider.add("book.pastel.guidebook.blood_orchid_products.page0.text", "[Blood Orchid](entry://general/blood_orchid) extracts have an intense effect when consumed: they can put the creature into a [#](449900)Frenzy[#]().\\\nDamage, attack speed, movement speed and knockback resistance are buffed with each kill. The higher the level of the effect, the greater the buff. Not scoring a kill in 10 seconds will apply a debuff instead.");
		provider.add("book.pastel.guidebook.blood_orchid_products.page1.text", "Rather than resetting the duration, applying another [#](449900)Frenzy[#]() effect will instead increase its potency.\\\n\\\nTo get the most out of the effect, I should apply a long duration effect first, then stack up with shorter, but more potent ones.");
		provider.add("book.pastel.guidebook.blood_orchid_products.page1.title", "Frenzy Stacking");
		provider.add("book.pastel.guidebook.blood_orchid_products.page2.text", "I managed to extract the active ingredient of a Blood Orchid Petal into a thick solution. It almost smells like rose water, but its effect is definitely... *a little more effervescent*.");
		provider.add("book.pastel.guidebook.blood_orchid_products.page3.text", "The [#](449900)Frenzy[#]() effect starts low, but lasts a bit longer.");
		provider.add("book.pastel.guidebook.blood_orchid_products.page4.text", "The [#](449900)Frenzy[#]() effect is relatively short, but starts off quite powerful.");
		provider.add("book.pastel.guidebook.blood_orchid_products.page5.text", "A truly nasty brew. It tastes exactly as you would expect.");
	}
}
